<script lang="ts">
  import type { PageData } from './$types'; import { graphql } from '#lib/api.ts'; import { ARCHIVE, RESTORE } from '#lib/queries.ts'; import { refreshAll } from '$app/navigation';
  let { data }: { data: PageData } = $props(); let pending = $state(''); let message = $state('');
  async function toggle(id: string, active: boolean) { if (active && !window.confirm('Скрыть товар из витрины? Его можно будет восстановить.')) return; pending = id; message = ''; try { await graphql(active ? ARCHIVE : RESTORE, { id }); await refreshAll(); } catch (e) { message = (e as Error).message; } finally { pending = ''; } }
  function pageHref(page: number) { const q = new URLSearchParams({ page: String(page), search: data.search, status: data.statusParam }); if (data.categoryId) q.set('category', data.categoryId); return `/admin/products?${q}`; }
</script>
<svelte:head><title>Товары — Орбита-строй</title></svelte:head>
<div class="flex flex-wrap items-center justify-between gap-4"><div><h1 class="text-3xl font-bold">Товары</h1><p class="mt-2 text-muted">{data.adminProducts.paginatorInfo.total} карточек в каталоге</p></div><a class="button" href="/admin/products/new">Создать товар</a></div>
<form class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-[2fr_2fr_1fr_auto]" action="/admin/products" method="GET"><div><label class="label" for="search">Поиск по названию</label><input class="field" id="search" name="search" value={data.search}/></div><div><label class="label" for="category">Категория</label><select class="field" id="category" name="category" value={data.categoryId || ''}><option value="">Все категории</option>{#each data.referenceData.categories as category}<option value={category.id}>{category.value}</option>{/each}</select></div><div><label class="label" for="status">Статус</label><select class="field" id="status" name="status" value={data.statusParam}><option value="">Все</option><option value="active">Активные</option><option value="archived">Отключённые</option></select></div><button class="button mt-auto">Найти</button></form>
{#if data.error || message}<p role="alert" class="notice notice-error mt-6">{message || data.error}</p>{/if}
<div class="mt-6 overflow-x-auto rounded-md border border-slate-200 bg-white"><table class="w-full text-left"><thead class="bg-slate-50 text-sm text-muted"><tr><th class="p-4">Товар</th><th class="p-4">Цена</th><th class="p-4">Статус</th><th class="p-4"><span class="sr-only">Действия</span></th></tr></thead><tbody>{#each data.adminProducts.data as product}<tr class="border-t border-slate-200"><td class="min-w-48 p-4"><a class="font-semibold text-brand underline" href={`/admin/products/${product.id}`}>{product.value}</a><span class="mt-1 block text-xs text-muted">ID {product.id}</span></td><td class="whitespace-nowrap p-4 tabular-nums">{product.price?.value ?? '—'} ₽ / {product.unit?.value ?? '—'}</td><td class="p-4">{product.is_active ? 'Активен' : 'Отключён'}</td><td class="p-4"><button class="button button-secondary whitespace-nowrap" disabled={pending === product.id} onclick={() => toggle(product.id, product.is_active)}>{pending === product.id ? 'Сохраняем…' : product.is_active ? 'Отключить' : 'Восстановить'}</button></td></tr>{:else}<tr><td class="p-8 text-center text-muted" colspan="4">{data.error ? 'Каталог недоступен' : 'Товары не найдены. Измените параметры поиска.'}</td></tr>{/each}</tbody></table></div>
<nav class="mt-6 flex items-center justify-between gap-3" aria-label="Страницы каталога">{#if data.adminProducts.paginatorInfo.currentPage > 1}<a class="button button-secondary" href={pageHref(data.adminProducts.paginatorInfo.currentPage - 1)}>Назад</a>{:else}<span></span>{/if}<span class="text-sm text-muted">Страница {data.adminProducts.paginatorInfo.currentPage} из {data.adminProducts.paginatorInfo.lastPage}</span>{#if data.adminProducts.paginatorInfo.currentPage < data.adminProducts.paginatorInfo.lastPage}<a class="button button-secondary" href={pageHref(data.adminProducts.paginatorInfo.currentPage + 1)}>Далее</a>{:else}<span></span>{/if}</nav>
